namespace Glacier.Compute.Memory;

public sealed class DeviceMemoryPool : IDisposable
{
    public struct GpuBufferSpan { public int DeviceId; }
    public class CommandStream { }
    private class PerDeviceSlabArena { public PerDeviceSlabArena(int id) { } public GpuBufferSpan Allocate(long l, CommandStream s) => default; public void Recycle(GpuBufferSpan sp, CommandStream s) { } }

    private readonly ConcurrentDictionary<int, PerDeviceSlabArena> _deviceArenas = new();
    public GpuBufferSpan Rent(long byteLength, int deviceId, CommandStream stream)
    {
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(byteLength);
        var arena = _deviceArenas.GetOrAdd(deviceId, id => new PerDeviceSlabArena(id));
        return arena.Allocate(byteLength, stream);
    }
    public void Return(GpuBufferSpan span, CommandStream stream)
    {
        var arena = _deviceArenas[span.DeviceId];
        arena.Recycle(span, stream);
    }
    public void Dispose() => GC.SuppressFinalize(this);
}

