using System;
using System.IO;
using System.IO.MemoryMappedFiles;

namespace Glacier.Inference.Memory;

public sealed unsafe class TieredVirtualMemoryManager : IDisposable
{
    public byte* MapWeightRange(string modelPath, long fileOffset, long length, bool prefault = false)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(modelPath);
        ArgumentOutOfRangeException.ThrowIfNegative(fileOffset);
        long alignedOffset = fileOffset & ~0xFFFL; // Align to 4KB OS page boundary
        long delta = fileOffset - alignedOffset;
        var mmf = MemoryMappedFile.CreateFromFile(modelPath, FileMode.Open, null, 0, MemoryMappedFileAccess.Read);
        var accessor = mmf.CreateViewAccessor(alignedOffset, length + delta, MemoryMappedFileAccess.Read);
        byte* basePtr = null;
        accessor.SafeMemoryMappedViewHandle.AcquirePointer(ref basePtr);
        return basePtr + delta;
    }
    public void Dispose() => GC.SuppressFinalize(this);
}

