// Namespace: Glacier.Cluster.Protocol
using System;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace Glacier.Cluster.Protocol;

[Flags]
public enum SimdArchitectureFlags { None = 0, Avx2 = 1, Avx512F = 2, Neon = 4 }
[Flags]
public enum GpuBackendFlags { None = 0, Cuda = 1 }

public sealed record NodeHardwareProfile
{
    public string NodeId { get; init; } = Environment.MachineName;
    public int LogicalCores { get; init; } = Environment.ProcessorCount;
    public SimdArchitectureFlags SimdFlags { get; init; }
    public GpuBackendFlags GpuFlags { get; init; }
    public ulong TotalPhysicalMemoryBytes { get; init; }
    public ulong TotalVramBytes { get; init; }

    public static NodeHardwareProfile ProbeCurrentNode()
    {
        SimdArchitectureFlags simd = SimdArchitectureFlags.None;
        if (Vector512.IsHardwareAccelerated) simd |= SimdArchitectureFlags.Avx512F;
        if (Avx2.IsSupported) simd |= SimdArchitectureFlags.Avx2;
        if (AdvSimd.IsSupported) simd |= SimdArchitectureFlags.Neon;
        return new NodeHardwareProfile { SimdFlags = simd, TotalPhysicalMemoryBytes = (ulong)GC.GetGCMemoryInfo().TotalAvailableMemoryBytes };
    }
}

