using System;
using System.Buffers;

namespace Glacier.Polaris.Memory;

public interface IColumn<T> { ReadOnlySpan<T> Values { get; } bool IsNull(int index); }

public sealed class MemoryOwnerColumn<T> : IColumn<T> where T : unmanaged
{
    private readonly IMemoryOwner<T> _owner;
    private readonly int _length;
    private readonly NativeMemoryOwner<ulong>? _validityMask;
    public ReadOnlySpan<T> Values => _owner.Memory.Span.Slice(0, _length);
    public bool IsNull(int index) => _validityMask != null && ((_validityMask.GetSpan()[index >> 6] & (1UL << (index & 63))) == 0);
    public MemoryOwnerColumn(IMemoryOwner<T> owner, int length, NativeMemoryOwner<ulong>? validityMask = null)
    {
        _owner = owner ?? throw new ArgumentNullException(nameof(owner));
        _length = length;
        _validityMask = validityMask;
    }
}

