using System;
using System.Buffers.Binary;
using System.IO.Pipelines;
using System.Threading;
using System.Threading.Tasks;

namespace Glacier.Storage.Arrow;

public sealed class ArrowRecordBatch
{
    public int CalculateMetadataLength() => 64;
    public void SerializeMetadata(Span<byte> destination) { }
}

public sealed class ArrowIpcStreamWriter
{
    public static async ValueTask WriteRecordBatchAsync(PipeWriter writer, ArrowRecordBatch batch, CancellationToken ct = default)
    {
        int flatbuffersMetadataLength = batch.CalculateMetadataLength();
        Memory<byte> headerMem = writer.GetMemory(8 + flatbuffersMetadataLength);
        BinaryPrimitives.WriteInt32LittleEndian(headerMem.Span.Slice(0, 4), -1); // Continuation token
        BinaryPrimitives.WriteInt32LittleEndian(headerMem.Span.Slice(4, 4), flatbuffersMetadataLength);
        batch.SerializeMetadata(headerMem.Span.Slice(8, flatbuffersMetadataLength));
        writer.Advance(8 + flatbuffersMetadataLength);
        await writer.FlushAsync(ct);
    }
}

