using System;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

namespace Glacier.Agent.Mcp;

public interface IMcpTransport
{
    ValueTask<JsonElement> SendRequestAsync(string method, JsonElement parameters, CancellationToken ct = default);
}

public sealed class InMemoryMcpTransport : IMcpTransport
{
    private long _idCounter;
    public ValueTask<JsonElement> SendRequestAsync(string method, JsonElement parameters, CancellationToken ct = default)
    {
        long reqId = Interlocked.Increment(ref _idCounter);
        return ValueTask.FromResult(default(JsonElement));
    }
}

